  // 3.0: Simple help and the install-statistics question
  'simple.help.g1.title': 'Een scherm verbinden',
  'simple.help.g1.s1': 'Open de player op de tv, tablet of computer die je wilt gebruiken: installeer de Android-app, of open de pagina /player van deze site in de browser.',
  'simple.help.g1.s2': 'Geen tv bij de hand? Open de player in een ander browsertabblad om het uit te proberen.',
  'simple.help.g1.s3': 'De player toont een code van 6 cijfers. Kies hier ‘Scherm toevoegen’ en typ hem in.',
  'simple.help.g1.s4': 'Geef het scherm een naam die je herkent, zoals ‘Etalage’.',
  'simple.help.g2.title': 'Wijzigen wat een scherm toont',
  'simple.help.g2.s1': 'Kies ‘Wijzigen wat een scherm toont’ of tik op het scherm onder ‘Je schermen’.',
  'simple.help.g2.s2': 'Kies ‘Vervangen’ om alleen het nieuwe te tonen, of ‘Toevoegen’ om te houden wat al speelt.',
  'simple.help.g2.s3': 'Upload foto’s of video’s, kies eerder geüploade, of toon hetzelfde als een ander scherm.',
  'simple.help.g2.s4': 'Het scherm werkt binnen een paar seconden bij.',
  'simple.help.g3.title': 'Foto’s en video’s uploaden',
  'simple.help.g3.s1': 'Kies ‘Foto\'s uploaden’ en selecteer zoveel bestanden als je wilt, of sleep ze erin.',
  'simple.help.g3.s2': 'Vink de schermen aan die ze moeten tonen, of vink ze allemaal uit om ze voor later te bewaren.',
  'simple.help.g3.s3': 'Foto’s worden elk 10 seconden getoond; video’s spelen tot het einde.',
  'simple.help.q1': 'Wat kan ik als scherm gebruiken?',
  'simple.help.a1': 'Android-tv’s, tv-boxen en tablets, Fire TV, smart-tv’s van LG en Samsung, Raspberry Pi, Windows en ChromeOS, of elk apparaat met een webbrowser.',
  'simple.help.q2': 'Mijn scherm verandert niet. Wat moet ik controleren?',
  'simple.help.a2': 'Controleer of het scherm op de startpagina ‘Speelt af’ toont. Staat er ‘Offline’, controleer dan of het apparaat aanstaat en met internet verbonden is; je wijzigingen komen binnen zodra het weer verbonden is.',
  'simple.help.q3': 'Wat gebeurt er als internet uitvalt?',
  'simple.help.a3': 'Schermen bewaren de inhoud lokaal en blijven die afspelen. Nieuwe wijzigingen komen binnen zodra de verbinding terug is.',
  'simple.help.q4': 'Welke bestanden kan ik uploaden?',
  'simple.help.a4': 'Foto’s (JPEG, PNG, GIF, WebP) en video’s (MP4 werkt het best), plus audio. PDF’s upload je via de pagina Inhoud in de weergave ‘Geavanceerd’.',
  'simple.help.q5': 'Hoe geef ik een scherm een andere naam of verwijder ik het?',
  'simple.help.a5': 'Schakel rechtsboven naar ‘Geavanceerd’, open ‘Schermen’, klik op het scherm en gebruik bovenaan de pagina Naam wijzigen of Verwijderen.',
  'simple.help.q6': 'Kan ik op verschillende tijden verschillende dingen tonen?',
  'simple.help.a6': 'Ja, dat is ‘Planning’ in de weergave ‘Geavanceerd’. De eenvoudige weergave toont op een scherm altijd dezelfde inhoud tot je die wijzigt.',
  'simple.help.trial_q': 'Hoe werkt de gratis proefperiode?',
  'simple.help.trial_a': 'Je krijgt 14 dagen het Pro-abonnement met alle functies, zonder creditcard. Daarna ga je naar het Free-abonnement: er wordt niets verwijderd, en schermen boven de limiet van Free pauzeren tot je een abonnement kiest.',
  'stats.prompt.title': 'Help je ons te laten zien hoe breed ScreenTinker wordt gebruikt?',
  'stats.prompt.body': 'Omdat de meeste installaties privé zijn, weten we niet hoeveel schermen er zijn. Bij delen worden een willekeurige ID, de versie en het aantal schermen verstuurd, verder niets, nooit. Je kunt dit altijd wijzigen in Instellingen.',
  'stats.prompt.share': 'Delen',
  'stats.prompt.no': 'Nee, bedankt',
  'stats.prompt.thanks': 'Bedankt, installatiestatistieken worden gedeeld',
