  'migrate.how.xibo': 'Open in Xibo Administration en daarna Applications, en voeg een Application toe met ‘Client Credentials’ aangevinkt. Kopieer de Client ID en het Client Secret. Vul het adres van je CMS in (waar je je aanmeldt), bijvoorbeeld https://cms.example.com.',
  'migrate.how.yodeck': 'Open in Yodeck Account Settings, Advanced Settings, API Tokens en genereer een token (Premium- of Enterprise-abonnement). Plak het als label:token. Yodeck geeft de oorspronkelijk geüploade afbeeldingen en documenten niet vrij via de API: die worden opgesomd, zodat je ze kunt toevoegen met de zip-import. Video’s komen over in de versie die Yodeck afspeelt.',
  'migrate.how.optisigns': 'OptiSigns heeft een API, maar documenteert geen manier om je bestanden te downloaden, dus een afspeellijst zou leeg aankomen. Download je bestanden uit OptiSigns en gebruik de zip-import: één map per afspeellijst, of een playlists.csv.',
  'migrate.how.screencloud': 'Open in ScreenCloud Studio Account Settings en daarna het tabblad Developer, en maak een token met leesrechten. Kies de regio die daar staat (EU of US). ScreenCloud bewaart tijdregels bij losse kanaalitems; die worden opgesomd, niet geïmporteerd.',
  'migrate.how.anthias': 'Vul het adres van je Anthias-apparaat in, bijvoorbeeld http://192.168.1.20. Als je authenticatie hebt aangezet, vul dan de gebruikersnaam en het wachtwoord in. Elk apparaat wordt geïmporteerd als één scherm met één afspeellijst.',
  'migrate.how.screenly': 'Open in Screenly Settings, Security, Tokens en voeg een token toe. Afspeellijsten, labels en schermen komen mee; eenvoudige dag- en tijdregels worden planningen.',
  'migrate.how.generic_zip': 'Upload een zip met je media. Elke map wordt een afspeellijst. Voeg eventueel playlists.csv toe (kolommen: playlist, file, duration, order) en screens.csv (kolommen: name, group, playlist).',
